output_text:
[
  {
    "id": "must_use_cart_for_trip",
    "text": "A shopper is obliged to obtain a cart at the start of the shopping trip.",
    "abstraction": {
      "state_properties": {
        "cart_possessed": "hasCart"
      },
      "events": {
        "take_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "cart_possessed"
    }
  },
  {
    "id": "exit_with_cart",
    "text": "A shopper is forbidden from leaving the store without the cart.",
    "abstraction": {
      "state_properties": {
        "leaving_store": "EXIT"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leaving_store",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_in_single_file_shelf_aisles",
    "text": "Carts are forbidden in single-file shelf aisles where the shopper has only one cell of clearance across the aisle.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            "adjShelf",
            {
              "or": [
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                },
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_aisle"
        ]
      }
    }
  },
  {
    "id": "enter_single_file_without_cart",
    "text": "A shopper is forbidden from entering a single-file shelf aisle while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            "adjShelf",
            {
              "or": [
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                },
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {
        "enter_single_file_shelf_aisle": {
          "pre": {
            "and": [
              "MOVE",
              {
                "not": "single_file_shelf_aisle"
              }
            ]
          },
          "post": "single_file_shelf_aisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "enter_single_file_shelf_aisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "collect_in_single_file_without_cart",
    "text": "Shelf interactions inside single-file shelf aisles must be performed without a cart.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            "adjShelf",
            {
              "or": [
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                },
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {
        "shelf_interaction_in_single_file_aisle": {
          "pre": {
            "and": [
              "INTERACT",
              "single_file_shelf_aisle"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "shelf_interaction_in_single_file_aisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "recover_parked_cart",
    "text": "Whenever a shopper parks or releases a cart during the trip, they are obliged to retrieve a cart again before leaving.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "park_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieve_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "park_cart",
      "discharge": "retrieve_cart"
    }
  },
  {
    "id": "no_cartless_roaming_in_open_store",
    "text": "After setting down a cart, a shopper may move cartless only within a single-file shelf aisle or while entering one, not roam through open store space.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            "adjShelf",
            {
              "or": [
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                },
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {
        "enter_single_file_shelf_aisle": {
          "pre": {
            "and": [
              "MOVE",
              {
                "not": "single_file_shelf_aisle"
              }
            ]
          },
          "post": "single_file_shelf_aisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "single_file_shelf_aisle"
          },
          {
            "not": "enter_single_file_shelf_aisle"
          }
        ]
      }
    }
  },
  {
    "id": "handle_cart_only_in_wide_clear_space",
    "text": "Cart pickup, parking, and retrieval should occur only in wide clear space rather than in a shelf-side bottleneck.",
    "abstraction": {
      "state_properties": {
        "wide_clear_cart_handling_space": {
          "and": [
            {
              "not": "adjShelf"
            },
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            }
          ]
        }
      },
      "events": {
        "take_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        },
        "park_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cart_handling": {
          "pre": {
            "or": [
              "take_cart",
              "park_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_handling",
          {
            "not": "wide_clear_cart_handling_space"
          }
        ]
      }
    }
  }
]
